export const START='2026-10-01';
export const localDate=(d=new Date())=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);
export const dayOf=d=>new Date(d+'T12:00:00').getDay();
export const addDays=(d,n)=>{let t=new Date(d+'T12:00:00');t.setDate(t.getDate()+n);return t.getFullYear()+'-'+String(t.getMonth()+1).padStart(2,'0')+'-'+String(t.getDate()).padStart(2,'0')};
const all=[0,1,2,3,4,5,6];
export function initial(){const task=(id,time,title,kind,days=all,course='',remind=false,second=0)=>({id,time,title,kind,days,course,remind,second});return {version:1,started:localDate(),revisions:[{from:START,tasks:[task('arrive','06:20','Chegada / banho / desacelerar','routine'),task('sleep','07:00','Sono','routine'),task('wake','14:00','Acordar + alimentação','routine'),task('gym','14:30','Academia','gym',[1,3,5],'',true),task('bath','16:00','Banho + alimentação','routine'),task('sql','16:30','Curso principal — SQL','main',all,'SQL',true,30),task('break','17:30','Pausa','rest'),task('technical','17:50','Bloco técnico','technical',[1,2,3,4,5,6],'',true),task('read','18:50','Leitura de livro','read',all,'',true),task('project','19:20','Prática / projeto','project',all,'',true,30),task('leisure','20:20','Lazer / descanso','leisure'),task('prepare','21:00','Alimentação + preparar-se para o trabalho','routine'),task('work','22:00','Trabalho','work')]}],days:{},courses:['SQL','Python','Power BI','Power Automate'].map(name=>({name,percent:0,start:'',end:'',status:'Não iniciado',principal:name==='SQL'})),settings:{notifications:false},pending:[]}};
export function schedule(s,date){let rev=s.revisions.filter(r=>r.from<=date).sort((a,b)=>b.from.localeCompare(a.from))[0]||s.revisions[0];return rev.tasks.filter(t=>t.days.includes(dayOf(date))).map(t=>{let x={...t,days:[...t.days]};if(t.id==='technical'&&!t.customTitle){x.course={1:'Power BI',2:'Python',3:'Power Automate',4:'Power BI',5:'Python',6:'Power Automate'}[dayOf(date)];x.title='Bloco técnico — '+x.course}if(dayOf(date)===0){if(t.id==='sql'&&!t.customTitle)x.title='Revisão SQL';if(t.id==='project'&&!t.customTitle)x.title='Projeto / revisão semanal'}return x}).sort((a,b)=>a.time.localeCompare(b.time)||a.id.localeCompare(b.id))};
export function day(s,date){return s.days[date]||{tasks:schedule(s,date),entries:{},closing:{}}}
export function ensure(s,date){if(!s.days[date])s.days[date]=day(s,date);return s.days[date]}
export function totals(d){let r={done:0,total:d.tasks.length,study:0,read:0,gym:0,project:0,sql:0,productive:0,leisure:0};for(let t of d.tasks){let e=d.entries[t.id]||{};let m=Number(e.minutes)||0;if(e.done)r.done++;if(['main','technical','project'].includes(t.kind)){r.study+=m;r.productive+=m}if(t.kind==='read'){r.read+=m;r.productive+=m}if(t.kind==='leisure'||t.kind==='rest')r.leisure+=m;if(t.kind==='gym'&&e.done)r.gym++;if(t.kind==='project'&&e.done)r.project++;if(t.course==='SQL')r.sql+=m;}r.percent=r.total?Math.round(r.done/r.total*100):0;return r}
export function level(d){let t=totals(d);let completed=kind=>{let a=d.tasks.filter(x=>x.kind===kind);return a.length===0||a.every(x=>d.entries[x.id]?.done)};if(t.sql<30)return {name:t.done||t.study?'Parcialmente cumprido':'Ainda não realizado',color:'partial',rank:0};let normal=completed('main')&&completed('technical')&&completed('read')&&completed('gym');if(normal&&completed('project'))return {name:'Dia excelente',color:'excellent',rank:3};if(normal)return {name:'Dia normal',color:'normal',rank:2};return {name:'Dia mínimo',color:'minimum',rank:1}}
export function streak(s,today){let dates=Object.keys(s.days).filter(d=>d<=today&&totals(s.days[d]).study>0).sort();let best=0,n=0,prev='';for(let d of dates){n=prev&&addDays(prev,1)===d?n+1:1;best=Math.max(best,n);prev=d}let current=0;let cursor=dates.includes(today)?today:addDays(today,-1);while(dates.includes(cursor)){current++;cursor=addDays(cursor,-1)}return {current,best}}
export function editSchedule(s,tasks,today){let rev=s.revisions.find(r=>r.from===today);if(rev)rev.tasks=tasks;else s.revisions.push({from:today,tasks});for(let date of Object.keys(s.days)){if(date>=today){const d=s.days[date];const next=schedule(s,date);const ids=new Set(next.map(x=>x.id));const completedRemoved=d.tasks.filter(x=>!ids.has(x.id)&&d.entries[x.id]?.done);d.tasks=[...next,...completedRemoved].sort((a,b)=>a.time.localeCompare(b.time))}}}
